/* Prototipo autónomo. No autentica usuarios ni se conecta con Django. */
'use strict';
const $ = (q, root = document) => root.querySelector(q);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 leaf:'M20 4c-8-2-16 2-15 9 1 7 10 8 13 1 2-4 2-10 2-10ZM4 21l11-12',
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 field:'M3 21V7l9-4 9 4v14M3 11h18M8 11v10M16 11v10M3 16h18',
 users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8M22 21v-2a4 4 0 0 0-3-3.9M16 3.1a4 4 0 0 1 0 7.8',
 team:'M9 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6M15 21H3v-2a5 5 0 0 1 10 0v2M17 4a3 3 0 0 1 0 6M21 21v-2a5 5 0 0 0-4-4',
 clock:'M12 8v4l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 scale:'M12 3v18M6 21h12M4 7h16M4 7l-3 7h6L4 7ZM20 7l-3 7h6l-3-7',
 lock:'M6 11h12v10H6zM8 11V7a4 4 0 0 1 8 0v4M12 15v2',
 chart:'M3 3v18h18M7 15l4-5 4 3 6-8',
 shield:'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7l-9-4ZM8 12l3 3 5-6',
 arrow:'M5 12h14M14 7l5 5-5 5',
 plus:'M12 5v14M5 12h14',
 down:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',
 calendar:'M4 5h16v16H4zM8 3v4M16 3v4M4 10h16',
 check:'M5 12l4 4L19 6',
 close:'M6 6l12 12M6 18 18 6',
 pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',
 sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
 trend:'M3 17l6-6 4 4 8-10M15 5h6v6',
 edit:'M14 5l5 5M4 20l5-1L21 7l-5-5L4 14v6Z',
 exit:'M9 3H3v18h6M9 12h12M16 7l5 5-5 5',
 menu:'M3 6h18M3 12h18M3 18h18',
 info:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
 reset:'M3 11a9 9 0 1 1 2 7M3 4v7h7',
 bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',
 sprout:'M12 21V10M12 14C4 15 2 8 3 4c7-1 10 3 9 10ZM12 10C11 4 17 1 21 3c0 5-4 8-9 7',
};
const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.leaf}"/></svg>`;
const money = n => new Intl.NumberFormat('es-CL', {maximumFractionDigits:2}).format(n);
const localNow = new Date();
const today = `${localNow.getFullYear()}-${String(localNow.getMonth()+1).padStart(2,'0')}-${String(localNow.getDate()).padStart(2,'0')}`;
const dateAt = offset => { const d=new Date(); d.setHours(12,0,0,0); d.setDate(d.getDate()+offset); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const longDate = (value=today) => new Date(`${value}T12:00:00`).toLocaleDateString('es-CL', {day:'numeric',month:'long',year:'numeric'});
const shortDate = value => new Date(`${value}T12:00:00`).toLocaleDateString('es-CL',{day:'2-digit',month:'short'});
const KEY = 'agrokodit-interfaces-v1';
function initialData(){
 const users=[
  {id:1,name:'Ana Martínez',username:'admin',role:'admin',active:true},
  {id:2,name:'Jorge Muñoz',username:'jefe',role:'jefe',active:true},
  {id:3,name:'Carolina Soto',username:'carolina',role:'jefe',active:true},
  {id:4,name:'Tomás Rojas',username:'trabajador',role:'trabajador',active:true},
  {id:5,name:'Diego Pérez',username:'diego',role:'trabajador',active:true},
  {id:6,name:'Valentina Silva',username:'valentina',role:'trabajador',active:true},
  {id:7,name:'Camila Torres',username:'camila',role:'trabajador',active:true},
  {id:8,name:'Benjamín Díaz',username:'benjamin',role:'trabajador',active:true},
  {id:9,name:'Matías González',username:'matias',role:'trabajador',active:true},
  {id:10,name:'Antonia Reyes',username:'antonia',role:'trabajador',active:true},
  {id:11,name:'Javiera López',username:'javiera',role:'trabajador',active:true},
  {id:12,name:'Felipe Castro',username:'felipe',role:'trabajador',active:true},
  {id:13,name:'Catalina Flores',username:'catalina',role:'trabajador',active:true}
 ];
 const pairs=[{id:1,name:'Collera 01',members:[4,5],team:1,active:true},{id:2,name:'Collera 02',members:[6,7],team:1,active:true},{id:3,name:'Collera 03',members:[8,9],team:1,active:true},{id:4,name:'Collera 04',members:[10,11],team:2,active:true}];
 const records=[]; let id=1;
 for(let day=-6;day<=0;day++) for(const pair of pairs){
  const cents = day===0 ? [156400,134200,118600,148800][pair.id-1] : 70000+(day+6)*9500+pair.id*6300;
  records.push({id:id++,date:dateAt(day),time:'10:35',pair:pair.id,pairName:pair.name,members:[...pair.members],team:pair.team,plot:pair.team===1?1:3,cents,loss:Math.round(cents*.012),quality:'Exportación',reason:'Fruta dañada',actor:pair.team===1?'Jorge Muñoz':'Carolina Soto'});
 }
 return {users,pairs,records,teams:[{id:1,name:'Cuadrilla Norte',chief:2},{id:2,name:'Cuadrilla Sur',chief:3}],fields:[{id:1,name:'Los Aromos',code:'PR-001',location:'Curicó, Región del Maule',active:true},{id:2,name:'Santa Elena',code:'PR-002',location:'Teno, Región del Maule',active:true}],orchards:[{id:1,name:'Huerto Los Cerezos',code:'HU-001',field:1,active:true},{id:2,name:'Huerto El Molino',code:'HU-002',field:2,active:true}],plots:[{id:1,name:'Cuartel A-01',code:'CA-01',orchard:1,crop:'Cerezas · Santina',area:8.5,active:true},{id:2,name:'Cuartel A-02',code:'CA-02',orchard:1,crop:'Cerezas · Lapins',area:6.2,active:true},{id:3,name:'Cuartel B-01',code:'CB-01',orchard:2,crop:'Cerezas · Regina',area:9.8,active:true}],seasons:[{id:1,name:'Temporada 2026 / 2027',start:'2026-09-01',end:'2027-04-30',active:true}],journals:[{team:1,date:today,closed:false,plot:1,labor:'Cosecha de cerezas',notes:''},{team:2,date:today,closed:false,plot:3,labor:'Cosecha de cerezas',notes:''}],attendance:users.filter(u=>u.role==='trabajador'&&u.id<12).map(u=>({user:u.id,date:today,team:u.id<10?1:2,entry:u.id===8?'08:18':'08:00',exit:'',absent:false,validated:false})),audit:[{date:new Date().toISOString(),actor:'Sistema',action:'Datos de ejemplo preparados',detail:'Prototipo de interfaces · temporada 2026 / 2027'}]};
}
let storageAvailable=true;
function loadData(){try{const raw=localStorage.getItem(KEY); if(raw){const saved=JSON.parse(raw); if(Array.isArray(saved.users)&&Array.isArray(saved.records)&&saved.journals?.[0]?.date===today)return saved;}}catch{storageAvailable=false;}return initialData();}
let db=loadData();
let role='admin';
let currentPage='inicio';
let active=false;
const labels={admin:'Administrador',jefe:'Jefe de Cuadrilla',trabajador:'Trabajador'};
const sessionUsers={admin:1,jefe:2,trabajador:4};
const user=()=>db.users.find(u=>u.id===sessionUsers[role]);
const find=(kind,id)=>db[kind].find(x=>x.id===Number(id));
const initials=name=>name.split(' ').slice(0,2).map(x=>x[0]).join('');
const badge=(text,type='')=>`<span class="badge ${type}">${esc(text)}</span>`;
const button=(text,action,ico='',kind='',extra='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const linkButton=(text,page,ico='',kind='')=>`<a class="btn ${kind}" href="#${page}">${ico?icon(ico):''}${text}</a>`;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));}catch{storageAvailable=false;toast('El navegador no permite guardar. Los cambios duran mientras esta página esté abierta.');}}
function log(action,detail){db.audit.unshift({date:new Date().toISOString(),actor:user().name,action,detail});save();}
let toastTimer;
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
const navItems=[['inicio','Resumen general','grid',['admin','jefe','trabajador']],['predios','Predios y temporadas','field',['admin']],['usuarios','Usuarios y roles','users',['admin']],['equipos','Cuadrillas y colleras','team',['admin','jefe']],['asistencia','Asistencia','clock',['jefe']],['kilos','Registrar kilos','scale',['jefe']],['cierre','Cierre de jornada','lock',['admin','jefe']],['mi-asistencia','Mi asistencia','clock',['trabajador']],['mi-produccion','Mi producción','scale',['trabajador']],['reportes','Reportes y rankings','chart',['admin','jefe']],['auditoria','Auditoría','shield',['admin']]];
function scoped(records=db.records){return records.filter(r=>role==='admin'||(role==='jefe'?r.team===1:r.members.includes(user().id)));}
const currentRecords=()=>scoped().filter(r=>r.date===today);
const total=(records,prop='cents')=>records.reduce((n,r)=>n+r[prop],0)/100;
const journal=(team=1)=>db.journals.find(j=>j.team===team&&j.date===today);
const seasonOpen=()=>db.seasons.some(s=>s.active&&s.start<=today&&s.end>=today);
const isOpen=(team=1)=>!!journal(team)&&!journal(team).closed&&seasonOpen();
function fieldFor(plotId){const plot=find('plots',plotId);const orchard=find('orchards',plot?.orchard);return find('fields',orchard?.field);}
function layout(page){
 const title=navItems.find(n=>n[0]===page)?.[1]||'Resumen general';
 const season=db.seasons.find(s=>s.active)||db.seasons.at(-1);
 return `<div class="shell"><aside class="sidebar" id="sidebar"><a href="#inicio" class="brand">${icon('leaf')}<span>Agro<span>KODIT</span></span></a><div class="brand-sub">GESTIÓN AGRÍCOLA</div><p class="nav-label">ESPACIO DE TRABAJO</p><nav class="nav" aria-label="Menú principal">${navItems.filter(n=>n[3].includes(role)).map(n=>`<a href="#${n[0]}" class="${n[0]===page?'active':''}" ${n[0]===page?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span>${n[0]===page?'<i class="nav-dot"></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="season-card"><div class="eyebrow">TU TEMPORADA</div><strong>${esc(season?.name||'Sin temporada')}</strong><small><i class="status-dot"></i>${seasonOpen()?'En curso':'Fuera de vigencia'}</small></div><div class="side-foot"><span>AgroKODIT © 2026</span><button data-action="logout" title="Volver a selección de perfil" aria-label="Volver a selección de perfil">${icon('exit')}</button></div></div></aside><div class="mobile-overlay" data-action="menu-close"></div><div class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="menu" aria-label="Abrir menú" aria-expanded="false" aria-controls="sidebar">${icon('menu')}</button><div class="breadcrumb">Espacio de trabajo <span>/</span><span>${esc(title)}</span></div><div class="topbar-right"><span class="demo-pill">Prototipo · datos de ejemplo</span><div class="profile"><div class="avatar">${initials(user().name)}</div><div><label for="profile">Vista de demostración</label><select id="profile" aria-label="Cambiar perfil de demostración">${Object.keys(labels).map(r=>`<option value="${r}" ${r===role?'selected':''}>${esc(labels[r])}</option>`).join('')}</select></div></div></div></header><main class="main" id="content" tabindex="-1">${renderPage(page)}<footer class="footer"><span>${icon('leaf')} Cultivando datos, cosechando decisiones.</span><span>Prototipo local · ${storageAvailable?'Cambios guardados en este navegador':'Cambios temporales'} · ${button('Restablecer demo','reset','','small')}</span></footer></main></div></div>`;
}
function header(title,sub,actions='',eyebrow='AGROKODIT / OPERACIÓN AGRÍCOLA'){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-actions">${actions}</div></div>`;}
function context(){return `<div class="context"><div class="context-left">${icon('sprout')}<strong>${esc(db.seasons.find(s=>s.active)?.name||'Sin temporada activa')}</strong><span class="divider"></span><span>${role==='admin'?'Todos los predios':role==='jefe'?'Cuadrilla Norte · Los Aromos':'Los Aromos · Huerto Los Cerezos'}</span><span class="divider"></span><span>${shortDate(today)}</span></div>${badge('Jornada de cosecha')}</div>`;}
function stat(label,value,unit,note,ico,featured=false){return `<article class="stat ${featured?'featured':''}"><div class="stat-top">${label}${icon(ico)}</div><div class="stat-value">${value}<span>${unit}</span></div><div class="stat-note">${note}</div></article>`;}
function stats(){const rec=currentRecords(), attendance=db.attendance.filter(a=>role==='admin'||(role==='jefe'?a.team===1:a.user===user().id));return `<div class="stats">${stat(role==='trabajador'?'Producción de mi collera':'Producción de hoy',money(total(rec)),'kg',`${icon('check')} <strong>${rec.length} pesajes</strong> registrados hoy`,'scale',true)}${stat('Asistencia de hoy',attendance.filter(a=>a.entry&&!a.absent).length,`/ ${attendance.length}`,`${attendance.filter(a=>a.entry>'08:00').length} ingreso(s) con atraso`,'users')}${stat(role==='trabajador'?'Mi equipo':'Colleras en terreno',role==='trabajador'?1:db.pairs.filter(p=>p.active&&(role==='admin'||p.team===1)).length,'colleras','Equipos de dos trabajadores','team')}${stat('Mermas registradas',money(total(rec,'loss')),'kg',`${money(total(rec)?total(rec,'loss')/total(rec)*100:0)}% respecto de los kilos registrados`,'leaf')}</div>`;}
function productionChart(records=scoped()){
 const days=Array.from({length:7},(_,i)=>dateAt(i-6));const vals=days.map(d=>total(records.filter(r=>r.date===d)));const max=Math.max(100,...vals)*1.15;
 return `<div class="chart" role="img" aria-label="Producción diaria de los últimos siete días: ${days.map((d,i)=>`${shortDate(d)}: ${money(vals[i])} kilos`).join('; ')}"><div class="y-axis">${[1,.75,.5,.25,0].map(p=>`<span>${money(Math.round(max*p/100)*100)}</span>`).join('')}</div><div class="plot">${days.map((d,i)=>`<div class="bar-group"><div class="bars"><div class="bar current" style="height:${vals[i]/max*100}%" title="${shortDate(d)}: ${money(vals[i])} kg"></div></div><span class="bar-label">${new Date(d+'T12:00:00').toLocaleDateString('es-CL',{weekday:'short'}).replace('.','')}</span></div>`).join('')}</div></div><div class="chart-summary"><span>Acumulado de los últimos 7 días <strong>${money(total(records.filter(r=>days.includes(r.date))))} kg</strong></span><span>Unidad: kilogramos</span></div>`;
}
function ranking(records=scoped()){
 const pairs=Object.values(records.reduce((all,r)=>{all[r.pair]??={name:r.pairName,cents:0};all[r.pair].cents+=r.cents;return all;},{})).sort((a,b)=>b.cents-a.cents);
 return pairs.length?`<div class="ranking">${pairs.slice(0,5).map((p,i)=>`<div class="rank-row"><span class="rank-number ${i===0?'first':''}">${String(i+1).padStart(2,'0')}</span><div><div class="rank-name">${esc(p.name)}</div><div class="progress"><span style="width:${p.cents/pairs[0].cents*100}%"></span></div></div><div class="rank-total">${money(p.cents/100)} <small>kg</small></div></div>`).join('')}</div>`:empty('Aún no hay producción para este período.');
}
const empty=text=>`<div class="empty">${icon('sprout')}<p>${text}</p></div>`;
function activity(limit=4){return `<div class="activity-list">${db.audit.slice(0,limit).map(a=>`<div class="activity"><span class="activity-mark">${icon('check')}</span><div><strong>${esc(a.action)}</strong><p>${esc(a.actor)} · ${new Date(a.date).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}</p></div></div>`).join('')}</div>`;}
function teamTable(){const teams=db.teams.filter(t=>role==='admin'||t.id===1);return `<div class="table-wrap"><table><thead><tr><th>Cuadrilla</th><th>Jefe responsable</th><th>Colleras</th><th>Producción hoy</th><th>Jornada</th></tr></thead><tbody>${teams.map(t=>`<tr><td><div class="cell-title"><span class="cell-symbol">${icon('team')}</span><span>${esc(t.name)}<small class="cell-sub">${esc(find('plots',journal(t.id)?.plot)?.name||'Sin cuartel')}</small></span></div></td><td>${esc(find('users',t.chief)?.name)}</td><td>${db.pairs.filter(p=>p.team===t.id&&p.active).length}</td><td><strong>${money(total(db.records.filter(r=>r.date===today&&r.team===t.id)))} kg</strong></td><td>${badge(journal(t.id)?.closed?'Cerrada':'Abierta',journal(t.id)?.closed?'gray':'')}</td></tr>`).join('')}</tbody></table></div>`;}
function dashboard(){
 if(role==='trabajador')return workerHome();
 return header(`Todo listo para una buena cosecha.`,`${role==='admin'?'Ana':'Jorge'}, aquí tienes el pulso de tu operación agrícola.`, `<span class="date-tag">${icon('calendar')}${longDate()}</span>${role==='admin'?linkButton('Ver reportes','reportes','chart'):linkButton('Registrar kilos','kilos','plus','primary')}`,'PANORAMA DEL DÍA')+context()+stats()+`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>El ritmo de la cosecha</h2><p>Producción de los últimos siete días</p></div><div class="legend"><span><i></i>Producción registrada</span></div></div><div class="panel-body">${productionChart()}</div></section><section class="panel"><div class="panel-head"><div><h2>Colleras destacadas</h2><p>Rendimiento acumulado · últimos 7 días</p></div>${icon('trend')}</div><div class="panel-body">${ranking()}</div><a href="#reportes" class="panel-foot">Ver ranking completo ${icon('arrow')}</a></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>La operación en terreno</h2><p>Estado de las cuadrillas durante la jornada</p></div>${badge('En vivo · demo')}</div>${teamTable()}<div class="table-caption"><span>${db.teams.filter(t=>role==='admin'||t.id===1).length} cuadrillas en tu vista</span><a href="#equipos">Ver equipos →</a></div></section><section class="panel"><div class="panel-head"><div><h2>Últimos movimientos</h2><p>Lo que está pasando en el campo</p></div>${icon('clock')}</div><div class="panel-body">${activity()}</div>${role==='admin'?'<a href="#auditoria" class="panel-foot">Abrir bitácora '+icon('arrow')+'</a>':''}</section></div>`;
}
function territories(){return header('Un campo bien organizado.','Predios, huertos y cuarteles: cada cosecha tiene su lugar.',button('Nueva temporada','new-season','calendar')+button('Nuevo predio','new-field','plus','primary'),'ESTRUCTURA AGRÍCOLA')+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Tu estructura territorial</h2><p>${db.fields.length} predios · ${db.orchards.length} huertos · ${db.plots.length} cuarteles</p></div>${icon('field')}</div>${db.fields.map(f=>`<details class="tree-predio" open><summary><div class="cell-title"><span class="cell-symbol">${icon('field')}</span><span>${esc(f.name)}<small class="cell-sub">${esc(f.code)} · ${esc(f.location)}</small></span></div>${badge(f.active?'Activo':'Inactivo',f.active?'':'gray')}</summary><div class="tree-content"><div class="actions">${button('Agregar huerto','new-orchard','plus','small',`data-id="${f.id}" ${!f.active?'disabled':''}`)}${button('Editar predio','edit-field','edit','small',`data-id="${f.id}"`)}${button(f.active?'Desactivar':'Activar','toggle-field','','small',`data-id="${f.id}"`)}</div>${db.orchards.filter(o=>o.field===f.id).map(o=>`<div class="orchard"><div class="orchard-head"><strong>${icon('sprout')} ${esc(o.name)}</strong>${button('Agregar cuartel','new-plot','plus','small',`data-id="${o.id}" ${!f.active?'disabled':''}`)}</div>${db.plots.filter(p=>p.orchard===o.id).map(p=>`<div class="plot-card"><div><strong>${esc(p.name)}</strong><p>${esc(p.crop)} · ${money(p.area)} ha · ${esc(p.code)}</p></div><div class="actions">${badge(p.active?'Activo':'Inactivo',p.active?'':'gray')}${button(p.active?'Desactivar':'Activar','toggle-plot','','small',`data-id="${p.id}"`)}</div></div>`).join('')||'<small>Este huerto aún no tiene cuarteles.</small>'}</div>`).join('')||'<p class="muted" style="margin-top:18px">Agrega un huerto para comenzar a organizar este predio.</p>'}</div></details>`).join('')||empty('Crea tu primer predio para comenzar.')}</section><div class="stack"><section class="panel"><div class="panel-head"><div><h2>Temporadas agrícolas</h2><p>Ciclos de trabajo y producción</p></div>${icon('calendar')}</div>${db.seasons.map(s=>`<div class="season-row"><div><strong>${esc(s.name)}</strong><p>${shortDate(s.start)} ${s.start.slice(0,4)} → ${shortDate(s.end)} ${s.end.slice(0,4)}</p><div style="margin-top:7px">${badge(s.active?'Abierta':'Cerrada',s.active?'':'gray')}</div></div>${s.active?button('Cerrar','close-season','lock','small',`data-id="${s.id}"`):''}</div>`).join('')}</section><aside class="help-card">${icon('info')}<h3>Todo conectado, todo trazable.</h3><p>Organiza cada predio en huertos y cada huerto en cuarteles. Los registros de cosecha conservan su ubicación, incluso si desactivas un sector.</p></aside></div></div>`;}
function userTable(){return `<div class="table-wrap"><table><thead><tr><th>Persona</th><th>Usuario</th><th>Perfil</th><th>Estado</th></tr></thead><tbody>${db.users.map(u=>`<tr data-search="${esc(`${u.name} ${u.username}`.toLowerCase())}" data-role="${u.role}"><td><div class="cell-title"><div class="avatar">${esc(initials(u.name))}</div>${esc(u.name)}</div></td><td>${esc(u.username)}</td><td>${badge(labels[u.role],u.role==='admin'?'amber':u.role==='jefe'?'blue':'')}</td><td>${badge(u.active?'Activo':'Inactivo',u.active?'':'gray')}</td></tr>`).join('')}</tbody></table></div>`;}
function usersPage(){return header('Las personas detrás de la cosecha.','Cuentas y perfiles del equipo de trabajo.',button('Nuevo usuario','new-user','plus','primary'),'PERSONAS Y ACCESOS')+`<section class="panel"><div class="toolbar"><div class="field search"><label for="user-search">Buscar persona</label><input id="user-search" type="search" placeholder="Nombre o usuario…"></div><div class="field"><label for="user-role">Perfil</label><select id="user-role"><option value="">Todos los perfiles</option>${Object.keys(labels).map(r=>`<option value="${r}">${labels[r]}</option>`).join('')}</select></div></div>${userTable()}<p id="user-empty" class="empty" hidden>No hay personas que coincidan con tu búsqueda.</p><div class="table-caption"><span>${db.users.length} personas registradas</span><span>Cuentas de demostración</span></div></section>`;}
function teamsPage(){const teams=db.teams.filter(t=>role==='admin'||t.id===1);return header(role==='admin'?'Un buen equipo hace la diferencia.':'Tu equipo, listo para terreno.','Cuadrillas y colleras organizadas para cada jornada.',role==='admin'?button('Nueva cuadrilla','new-team','team')+button('Formar collera','new-pair','plus','primary'):'','PERSONAS Y EQUIPOS')+`<div class="stack">${teams.map(t=>`<section class="panel"><div class="panel-head"><div><h2>${esc(t.name)}</h2><p>Jefe: ${esc(find('users',t.chief)?.name)} · ${db.pairs.filter(p=>p.team===t.id&&p.active).length} colleras activas</p></div>${badge('Equipo asignado')}</div><div class="panel-body"><div class="team-cards">${db.pairs.filter(p=>p.team===t.id&&p.active).map(p=>`<div class="team-card"><h3>${esc(p.name)}</h3><p>Dos personas, una misma meta.</p>${p.pendingTeam?`<div class="form-note">Próxima jornada: ${esc(find('teams',p.pendingTeam)?.name)}</div>`:''}${p.members.map(id=>`<div class="people"><span class="avatar">${esc(initials(find('users',id).name))}</span>${esc(find('users',id).name)}</div>`).join('')}${role==='admin'?`<div class="actions" style="margin-top:18px">${button('Trasladar','move-pair','arrow','small',`data-id="${p.id}"`)}${button('Desarmar','deactivate-pair','','small',`data-id="${p.id}"`)}</div>`:''}</div>`).join('')||empty('Esta cuadrilla aún no tiene colleras.')}</div></div></section>`).join('')}<aside class="help-card">${icon('shield')}<h3>Dos integrantes, sin duplicaciones.</h3><p>Cada collera activa se compone de dos trabajadores distintos. Un trabajador no puede pertenecer a dos colleras activas. Los traslados conservan los datos históricos de producción.</p></aside></div>`;}
function attendancePage(){const rows=db.attendance.filter(a=>a.date===today&&a.team===1);return header('Cada jornada comienza aquí.','Registra y valida la asistencia de tu cuadrilla.',button('Validar marcas','validate','check','primary',!isOpen()?'disabled':''),'CONTROL DE ASISTENCIA')+context()+(!isOpen()?`<div class="notice">${icon('lock')}La jornada está cerrada o no hay temporada vigente. Las marcas son de solo lectura.</div>`:'')+`<section class="panel"><div class="panel-head"><div><h2>Cuadrilla Norte</h2><p>Horario de inicio: 08:00 · ${longDate()}</p></div>${badge(`${rows.filter(a=>a.entry).length} presentes`)}</div><div class="table-wrap"><table><thead><tr><th>Trabajador</th><th>Entrada</th><th>Salida</th><th>Estado</th><th>Registro</th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(find('users',a.user).name)}</strong></td><td>${a.entry||'—'}</td><td>${a.exit||'—'}</td><td>${badge(a.absent?'Ausente':a.validated?'Validada':a.entry>'08:00'?'Con atraso':a.entry?'Presente':'Sin marca',a.absent?'red':a.entry>'08:00'?'amber':'')}</td><td><div class="attendance-actions">${isOpen()?`${!a.entry&&!a.absent?button('Entrada','attendance-entry','','small',`data-id="${a.user}"`):''}${a.entry&&!a.exit?button('Salida','attendance-exit','','small',`data-id="${a.user}"`):''}${!a.entry&&!a.absent?button('Ausente','attendance-absent','','small',`data-id="${a.user}"`):''}${a.exit?icon('check'):''}`:'—'}</div></td></tr>`).join('')}</tbody></table></div></section><div class="help-card" style="margin-top:22px">${icon('clock')}<h3>Marcas claras, horas exactas.</h3><p>Las salidas requieren una entrada previa. Las entradas posteriores a las 08:00 se identifican como atraso. Las horas se calculan a partir de ambas marcas, sin descontar pausas.</p></div>`;}
function option(value,label,selected=false){return `<option value="${esc(value)}" ${selected?'selected':''}>${esc(label)}</option>`;}
function field(name,label,type='text',value='',attrs='',hint=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</div>`;}
function select(name,label,options,attrs=''){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${attrs}>${options}</select></div>`;}
function kilosPage(){const j=journal();const pairs=db.pairs.filter(p=>p.active&&p.team===1);return header('Cada kilo cuenta.','Registra la producción de tu equipo con precisión y trazabilidad.','','REGISTRO DE PRODUCCIÓN')+context()+(!isOpen()?`<div class="notice">${icon('lock')}Jornada cerrada o temporada fuera de vigencia. No es posible registrar ni corregir pesajes.</div>`:'')+`<div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Nuevo pesaje</h2><p>Cuadrilla Norte · ${esc(find('plots',j?.plot)?.name||'Sin cuartel')}</p></div>${badge(isOpen()?'Jornada abierta':'Solo lectura',isOpen()?'':'gray')}</div><div class="panel-body"><form id="kilos-form"><fieldset ${!isOpen()?'disabled':''} style="border:0;padding:0;margin:0;min-width:0"><div class="form-grid">${select('pair','Collera',option('','Selecciona una collera')+pairs.map(p=>option(p.id,`${p.name} · ${p.members.map(id=>find('users',id).name.split(' ')[0]).join(' y ')}`)).join(''),'required')}${field('kilos','Kilos cosechados','number','','required min="0.01" max="999999.99" step="0.01" inputmode="decimal" placeholder="0,00"','Mayor que cero, con hasta 2 decimales.')}${select('quality','Calidad de la fruta',option('','Selecciona calidad')+['Exportación','Mercado nacional','Industrial'].map(q=>option(q,q)).join(''),'required')}${field('loss','Merma (kg)','number','0','required min="0" max="999999.99" step="0.01" inputmode="decimal"')}${field('reason','Motivo de merma','text','','maxlength="180" placeholder="Ej. fruta dañada"')}<div class="field"><label>Ubicación asignada</label><div class="form-note">${esc(fieldFor(j?.plot)?.name)} / ${esc(find('plots',j?.plot)?.name)}</div></div><div class="full form-note">${icon('shield')} El responsable, la fecha y la ubicación se asignan desde la jornada de demostración.</div></div><div class="form-error" id="kilos-error" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">${icon('plus')}Guardar pesaje</button></div></fieldset></form></div></section><div class="stack"><section class="panel"><div class="panel-head"><h2>Así va tu jornada</h2>${icon('scale')}</div><div class="panel-body"><div class="stat-value">${money(total(currentRecords()))}<span>kg registrados</span></div><div class="summary-list"><div><span>Pesajes de hoy</span><strong>${currentRecords().length}</strong></div><div><span>Mermas</span><strong>${money(total(currentRecords(),'loss'))} kg</strong></div><div><span>Responsable</span><strong>Jorge Muñoz</strong></div></div></div></section><aside class="help-card">${icon('info')}<h3>Antes de guardar</h3><p>Comprueba la collera y la calidad de la fruta. Podrás corregir los kilos mientras la jornada esté abierta; cada cambio quedará en la bitácora de esta demostración.</p></aside></div></div><section class="panel" style="margin-top:22px"><div class="panel-head"><h2>Últimos pesajes de hoy</h2>${badge(`${currentRecords().length} registros`)}</div>${recordsTable(currentRecords(),true)}</section>`;}
function recordsTable(records,editable=false){return records.length?`<div class="table-wrap"><table><thead><tr><th>Fecha / hora</th><th>Collera</th><th>Cuartel</th><th>Calidad</th><th>Kilos</th><th>Merma</th>${editable?'<th>Acciones</th>':''}</tr></thead><tbody>${[...records].reverse().map(r=>`<tr><td>${shortDate(r.date)}<small class="cell-sub">${r.time}</small></td><td><strong>${esc(r.pairName)}</strong></td><td>${esc(find('plots',r.plot)?.name)}</td><td>${badge(r.quality)}</td><td><strong>${money(r.cents/100)}</strong></td><td>${money(r.loss/100)}</td>${editable?`<td>${isOpen(r.team)?button('Corregir','edit-kilos','edit','small',`data-id="${r.id}"`):'—'}</td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('Aún no hay pesajes registrados en esta selección.');}
function closePage(){const teams=db.teams.filter(t=>role==='admin'||t.id===1);return header('Cierra el día con todo en orden.','Revisa la asistencia y la producción antes de sellar la jornada.','','CIERRE Y TRAZABILIDAD')+`<div class="stack">${teams.map(t=>{const j=journal(t.id),rec=db.records.filter(r=>r.date===today&&r.team===t.id),att=db.attendance.filter(a=>a.team===t.id),missing=att.filter(a=>!a.absent&&!a.exit).length;return `<section class="panel"><div class="panel-head"><div><h2>${esc(t.name)}</h2><p>${longDate()} · ${esc(find('users',t.chief).name)}</p></div>${badge(j?.closed?'Jornada cerrada':'Jornada abierta',j?.closed?'gray':'')}</div><div class="close-card"><div class="two-col"><div><div class="summary-list"><div><span>Producción registrada</span><strong>${money(total(rec))} kg</strong></div><div><span>Mermas registradas</span><strong>${money(total(rec,'loss'))} kg</strong></div><div><span>Trabajadores presentes</span><strong>${att.filter(a=>a.entry).length} / ${att.length}</strong></div><div><span>Pesajes</span><strong>${rec.length}</strong></div></div></div><div><div class="check-row">${icon('check')}Resumen de kilos y asistencia disponible</div><div class="check-row ${missing?'warning':''}">${icon(missing?'info':'check')}${missing?`${missing} trabajador(es) sin salida registrada`:'Todas las salidas están registradas'}</div><div class="check-row">${icon('shield')}Las correcciones quedan en la bitácora</div>${j?.closed?`<div class="notice success">${icon('lock')}Cerrada ${esc(j.closedAt||'')} por ${esc(j.closedBy||'el jefe de cuadrilla')}.</div>`:`<p class="muted" style="font-size:11px;margin:15px 0">Después del cierre, la asistencia y los pesajes quedan en modo de solo lectura.</p>`}<div class="actions">${role==='jefe'&&!j?.closed?button('Revisar y cerrar jornada','confirm-close','lock','primary',!seasonOpen()?'disabled':''):''}${role==='admin'&&j?.closed?button('Reabrir con motivo','reopen','reset','',`data-id="${t.id}"`):''}${role==='admin'&&!j?.closed?badge('Pendiente de cierre por su jefe','amber'):''}</div></div></div></div></section>`;}).join('')}</div>`;}
function reportsPage(){return header('Los datos también dan frutos.','Filtra la producción y descubre cómo está rindiendo tu equipo.',button('Descargar CSV','export','down')+button('Imprimir / PDF','print','chart'),'REPORTES Y RENDIMIENTO')+`<section class="panel" style="margin-bottom:22px"><form id="report-filters" class="toolbar">${field('from','Desde','date',dateAt(-6),'required')}${field('to','Hasta','date',today,'required')}${role==='admin'?select('field','Predio',option('','Todos los predios')+db.fields.map(f=>option(f.id,f.name)).join('')):''}${select('plot','Cuartel',option('','Todos los cuarteles')+db.plots.filter(p=>role==='admin'||p.id===1||p.id===2).map(p=>option(p.id,p.name)).join(''))}<button class="btn primary" type="submit">Aplicar filtros</button></form><div id="report-error" class="form-error" style="padding:0 23px" role="alert"></div></section><div id="report-content">${reportContent(scoped())}</div>`;}
let reportRows=[];
function reportContent(rows){reportRows=rows;return `<div class="stats">${stat('Producción filtrada',money(total(rows)),'kg','Total de pesajes seleccionados','scale',true)}${stat('Mermas',money(total(rows,'loss')),'kg','Pérdidas registradas','leaf')}${stat('Pesajes',rows.length,'registros','Según los filtros aplicados','chart')}${stat('Colleras',new Set(rows.map(r=>r.pair)).size,'equipos','Con producción en el período','team')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2>Evolución de la producción</h2><p>Últimos siete días, dentro del período filtrado</p></div></div><div class="panel-body">${productionChart(rows)}</div></section><section class="panel"><div class="panel-head"><div><h2>Ranking de colleras</h2><p>Ordenado por kilos registrados</p></div></div><div class="panel-body">${ranking(rows)}</div></section></div><section class="panel"><div class="panel-head"><h2>Detalle de producción</h2>${badge(`${rows.length} pesajes`)}</div>${recordsTable(rows)}</section>`;}
function auditPage(){return header('Cada movimiento deja su huella.','Trazabilidad de las acciones realizadas en esta demostración.','','AUDITORÍA')+`<section class="panel"><div class="panel-head"><div><h2>Bitácora de actividad</h2><p>Del evento más reciente al más antiguo</p></div>${badge(`${db.audit.length} eventos`)}</div><div class="table-wrap"><table><thead><tr><th>Fecha y hora</th><th>Responsable</th><th>Acción</th><th>Detalle</th></tr></thead><tbody>${db.audit.map(a=>`<tr><td>${new Date(a.date).toLocaleString('es-CL')}</td><td>${esc(a.actor)}</td><td><strong>${esc(a.action)}</strong></td><td>${esc(a.detail)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function workerHome(){const p=db.pairs.find(p=>p.active&&p.members.includes(user().id)),j=journal(p?.team),plot=find('plots',j?.plot);return header('Hola, Tomás. Tu jornada, a la vista.','Consulta tu lugar de trabajo y el avance de tu collera.','','MI ESPACIO')+context()+`<div class="stats">${stat('Producción de mi collera',money(total(currentRecords())),'kg','Acumulado de hoy · no se divide por trabajador','scale',true)}${stat('Mi collera',p?.name.replace('Collera ','')||'—','','Dos trabajadores, un equipo','team')}${stat('Entrada de hoy',db.attendance.find(a=>a.user===user().id)?.entry||'—','','Registro realizado por tu jefe','clock')}${stat('Mi jornada',j?.closed?'Cerrada':'Abierta','','Cuadrilla Norte','sun')}</div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Tu lugar de trabajo hoy</h2>${badge('Asignación del día')}</div><div class="panel-body"><div class="summary-list"><div><span>Predio</span><strong>${esc(fieldFor(plot?.id)?.name)}</strong></div><div><span>Huerto</span><strong>${esc(find('orchards',plot?.orchard)?.name)}</strong></div><div><span>Cuartel</span><strong>${esc(plot?.name)}</strong></div><div><span>Labor</span><strong>${esc(j?.labor)}</strong></div><div><span>Compañero de collera</span><strong>${esc(find('users',p?.members.find(id=>id!==user().id))?.name)}</strong></div></div><div class="actions">${linkButton('Ver mi producción','mi-produccion','scale','primary')}${linkButton('Ver mi asistencia','mi-asistencia','clock')}</div></div></section><aside class="help-card">${icon('sprout')}<h3>Información clara, en tus manos.</h3><p>Esta vista muestra solamente tu asistencia y la producción de las colleras en las que participaste. Los kilos corresponden al total de la collera, sin atribuir una cantidad individual que no se ha medido.</p></aside></div>`;}
function personalAttendance(){const a=db.attendance.find(a=>a.user===user().id);const hours=a?.exit?((Number(a.exit.slice(0,2))*60+Number(a.exit.slice(3)))-(Number(a.entry.slice(0,2))*60+Number(a.entry.slice(3))))/60:0;return header('Tu tiempo en el campo.','Consulta tus marcas de asistencia y horas registradas.','','MI ASISTENCIA')+`<div class="notice success">${icon('info')}Tu jefe registra y valida la asistencia. La autogestión no está habilitada en esta jornada.</div><div class="stats">${stat('Horas completas registradas',money(hours),'h','Solo marcas con entrada y salida','clock',true)}${stat('Entrada de hoy',a?.entry||'—','','Inicio de tu jornada','calendar')}${stat('Salida de hoy',a?.exit||'Pendiente','','Fin de tu jornada','clock')}${stat('Estado',a?.validated?'Validada':'Pendiente','','Validación del jefe','check')}</div><section class="panel"><div class="panel-head"><h2>Mis registros disponibles</h2></div><div class="table-wrap personal-table"><table><thead><tr><th>Fecha</th><th>Entrada</th><th>Salida</th><th>Horas</th><th>Estado</th></tr></thead><tbody><tr><td>${longDate()}</td><td>${a?.entry||'—'}</td><td>${a?.exit||'—'}</td><td>${a?.exit?money(hours)+' h':'Pendiente'}</td><td>${badge(a?.validated?'Validada':'Por validar',a?.validated?'':'amber')}</td></tr></tbody></table></div></section>`;}
function personalProduction(){return header('El resultado de trabajar juntos.','Producción de las colleras en las que participaste.','','MI PRODUCCIÓN')+`<div class="stats">${stat('Producción de hoy',money(total(currentRecords())),'kg','Total de tu collera','scale',true)}${stat('Últimos siete días',money(total(scoped())),'kg','Kilos compartidos de la collera','chart')}${stat('Mermas de hoy',money(total(currentRecords(),'loss')),'kg','Registradas por tu jefe','leaf')}${stat('Pesajes de hoy',currentRecords().length,'registros','Consulta de solo lectura','check')}</div><section class="panel"><div class="panel-head"><h2>Mi historial de producción por collera</h2>${badge('Solo lectura')}</div>${recordsTable(scoped())}</section>`;}
function renderPage(page){return ({inicio:dashboard,predios:territories,usuarios:usersPage,equipos:teamsPage,asistencia:attendancePage,kilos:kilosPage,cierre:closePage,reportes:reportsPage,auditoria:auditPage,'mi-asistencia':personalAttendance,'mi-produccion':personalProduction}[page]||dashboard)();}
function render(){
 if(!active){renderLogin();return;}
 const hash=location.hash.slice(1)||'inicio';
 const allowed=navItems.filter(n=>n[3].includes(role)).map(n=>n[0]);
 currentPage=allowed.includes(hash)?hash:'inicio';
 if(currentPage!==hash)history.replaceState(null,'','#inicio');
 $('#app').innerHTML=layout(currentPage);
 bindPage();
}
function renderLogin(){document.title='AgroKODIT · Explorar interfaces';$('#app').innerHTML=`<div class="login-screen"><section class="login-art"><div class="brand">${icon('leaf')}<span>Agro<span>KODIT</span></span></div><div><div class="eyebrow" style="color:#aac19d;margin-bottom:18px">DEL CAMPO A LAS DECISIONES</div><h1>Una buena cosecha empieza con <em>un buen equipo.</em></h1><p>Personas, asistencia y producción. Toda tu operación agrícola en un mismo lugar.</p></div><div class="field-graphic" aria-hidden="true"></div><div class="login-bottom">HECHO PARA EL CAMPO CHILENO &nbsp; · &nbsp; 2026</div></section><section class="login-content"><div class="login-box"><span class="tagline">${icon('sprout')} Tu campo, mejor conectado.</span><h2>Bienvenido a AgroKODIT</h2><p>Elige un perfil para explorar sus interfaces.</p>${Object.entries(labels).map(([r,label])=>`<button class="role-choice" data-action="enter" data-role="${r}"><span class="role-icon">${icon(r==='admin'?'shield':r==='jefe'?'team':'leaf')}</span><span><strong>${label}</strong><small>${r==='admin'?'Organiza, supervisa y toma decisiones':r==='jefe'?'Gestiona tu equipo y la jornada':'Consulta tu asistencia y producción'}</small></span>${icon('arrow')}</button>`).join('')}<div class="login-hint"><strong>Prototipo de interfaces</strong><br>Datos de ejemplo. Los cambios se guardan solo en este navegador. No se requieren credenciales reales.</div></div></section></div>`;}
function navigateRole(next){role=next;active=true;location.hash='inicio';render();window.scrollTo(0,0);}
function modal(title,content,onSubmit){
 const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" type="button" data-action="modal-close" aria-label="Cerrar ventana">${icon('close')}</button></div><div class="modal-body"><form id="modal-form">${content}<div class="form-error" id="modal-error" role="alert"></div><div class="form-actions"><button type="button" class="btn" data-action="modal-close">Cancelar</button><button type="submit" class="btn primary">Confirmar</button></div></form></div>`;
 el.showModal();$('#modal-form').addEventListener('submit',e=>{e.preventDefault();try{onSubmit(Object.fromEntries(new FormData(e.target)));el.close();render();}catch(err){$('#modal-error').textContent=err.message;}});
}
const nextId=kind=>Math.max(0,...db[kind].map(x=>x.id))+1;
const must=(ok,msg)=>{if(!ok)throw new Error(msg);};
const text=value=>String(value||'').trim();
function confirmModal(title,description,callback,extra=''){modal(title,`<p>${description}</p>${extra}`,callback);}
function newUser(){modal('Nueva persona',`<p>Crea una cuenta de ejemplo para organizar tus equipos. No se crea una cuenta en Django.</p><div class="form-grid">${field('name','Nombre completo','text','','required maxlength="90"')}${field('username','Nombre de usuario','text','','required maxlength="40" pattern="[a-zA-Z0-9_.-]+"')}${select('role','Perfil',Object.keys(labels).map(r=>option(r,labels[r])).join(''),'required')}</div>`,v=>{must(text(v.name).length>=3,'Ingresa un nombre de al menos 3 caracteres.');must(!db.users.some(u=>u.username.toLowerCase()===v.username.toLowerCase()),'Ya existe una persona con ese usuario.');db.users.push({id:nextId('users'),name:text(v.name),username:v.username,role:v.role,active:true});log('Usuario de ejemplo creado',`${text(v.name)} · ${labels[v.role]}`);toast('Persona agregada a la demostración.');});}
function fieldModal(id){const f=find('fields',id);modal(f?'Editar predio':'Nuevo predio',`<div class="form-grid">${field('name','Nombre del predio','text',f?.name||'','required maxlength="80"')}${field('code','Código único','text',f?.code||'','required maxlength="20"')}${field('location','Ubicación','text',f?.location||'','required maxlength="120"')}</div>`,v=>{must(text(v.name)&&text(v.code)&&text(v.location),'Completa todos los campos.');must(!db.fields.some(x=>x.id!==f?.id&&(x.code.toLowerCase()===text(v.code).toLowerCase()||x.name.toLowerCase()===text(v.name).toLowerCase())),'Ya existe un predio con ese nombre o código.');const values={name:text(v.name),code:text(v.code),location:text(v.location)};if(f)Object.assign(f,values);else db.fields.push({id:nextId('fields'),...values,active:true});log(f?'Predio actualizado':'Predio creado',values.name);toast('Predio guardado.');});}
function newOrchard(id){const f=find('fields',id);must(f?.active,'Selecciona un predio activo.');modal('Nuevo huerto',`<p>Predio: ${esc(f.name)}</p><div class="form-grid">${field('name','Nombre','text','','required maxlength="80"')}${field('code','Código dentro del predio','text','','required maxlength="20"')}</div>`,v=>{must(text(v.name)&&text(v.code),'Completa el nombre y código.');must(!db.orchards.some(o=>o.field===f.id&&(o.name.toLowerCase()===text(v.name).toLowerCase()||o.code.toLowerCase()===text(v.code).toLowerCase())),'Ese nombre o código ya existe en este predio.');db.orchards.push({id:nextId('orchards'),field:f.id,name:text(v.name),code:text(v.code),active:true});log('Huerto creado',`${f.name} / ${text(v.name)}`);toast('Huerto agregado.');});}
function newPlot(id){const o=find('orchards',id);must(find('fields',o?.field)?.active,'El predio debe estar activo.');modal('Nuevo cuartel',`<p>Huerto: ${esc(o.name)}</p><div class="form-grid">${field('name','Nombre','text','','required maxlength="80"')}${field('code','Código dentro del huerto','text','','required maxlength="20"')}${field('crop','Cultivo y variedad','text','','required maxlength="80" placeholder="Cerezas · Santina"')}${field('area','Superficie (ha)','number','','required min="0.01" max="100000" step="0.01"')}</div>`,v=>{must(text(v.name)&&text(v.code)&&text(v.crop),'Completa todos los campos.');must(!db.plots.some(p=>p.orchard===o.id&&(p.code.toLowerCase()===text(v.code).toLowerCase()||p.name.toLowerCase()===text(v.name).toLowerCase())),'Ese cuartel ya existe en el huerto.');db.plots.push({id:nextId('plots'),orchard:o.id,name:text(v.name),code:text(v.code),crop:text(v.crop),area:Number(v.area),active:true});log('Cuartel creado',`${o.name} / ${text(v.name)}`);toast('Cuartel agregado.');});}
function newSeason(){modal('Abrir temporada',`<div class="form-grid">${field('name','Nombre de la temporada','text','','required maxlength="80" placeholder="Temporada 2027 / 2028"')}${field('start','Fecha de inicio','date',today,'required')}${field('end','Fecha de término','date','','required')}</div>`,v=>{must(!db.seasons.some(s=>s.active),'Cierra la temporada actual antes de abrir otra.');must(v.end>=v.start,'El término no puede ser anterior al inicio.');must(text(v.name),'Ingresa un nombre.');db.seasons.push({id:nextId('seasons'),name:text(v.name),start:v.start,end:v.end,active:true});log('Temporada abierta',text(v.name));toast('Temporada abierta en la demostración.');});}
function newPair(){const available=db.users.filter(u=>u.role==='trabajador'&&u.active&&!db.pairs.some(p=>p.active&&p.members.includes(u.id)));const opts=option('','Selecciona trabajador')+available.map(u=>option(u.id,u.name)).join('');modal('Formar collera',`<p>Solo aparecen trabajadores que no pertenecen a otra collera activa.</p><div class="form-grid">${field('name','Nombre de la collera','text','','required maxlength="60"')}${select('team','Cuadrilla',db.teams.map(t=>option(t.id,t.name)).join(''),'required')}${select('first','Primer integrante',opts,'required')}${select('second','Segundo integrante',opts,'required')}</div>`,v=>{must(v.first!==v.second,'La collera debe tener dos trabajadores distintos.');must(available.length>=2&&[v.first,v.second].every(id=>available.some(u=>u.id===Number(id))),'Selecciona dos trabajadores disponibles.');must(text(v.name),'Ingresa un nombre.');must(!db.pairs.some(p=>p.active&&p.name.toLowerCase()===text(v.name).toLowerCase()),'Ya existe una collera activa con ese nombre.');db.pairs.push({id:nextId('pairs'),name:text(v.name),members:[Number(v.first),Number(v.second)],team:Number(v.team),active:true});for(const id of [v.first,v.second]){if(!db.attendance.some(a=>a.user===Number(id)&&a.date===today))db.attendance.push({user:Number(id),team:Number(v.team),date:today,entry:'',exit:'',absent:false,validated:false});}log('Collera formada',text(v.name));toast('Collera creada con dos integrantes.');});}
function cents(value,allowZero=false){const raw=String(value).replace(',','.');must(/^\d+(\.\d{1,2})?$/.test(raw),'Ingresa un número válido con hasta dos decimales.');const n=Math.round(Number(raw)*100);must(Number.isSafeInteger(n)&&n<100000000&&(allowZero?n>=0:n>0),allowZero?'La merma debe ser cero o mayor y menor a 1.000.000 kg.':'Los kilos deben ser mayores que cero y menores a 1.000.000.');return n;}
function submitKilos(form){const v=Object.fromEntries(new FormData(form));try{must(role==='jefe'&&isOpen(),'La jornada no admite nuevos pesajes.');const p=find('pairs',v.pair);must(p?.active&&p.team===1,'Selecciona una collera activa de tu cuadrilla.');const amount=cents(v.kilos),loss=cents(v.loss,true);must(loss===0||text(v.reason),'Indica el motivo de la merma.');must(['Exportación','Mercado nacional','Industrial'].includes(v.quality),'Selecciona una calidad válida.');const j=journal();db.records.push({id:nextId('records'),date:today,time:new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'}),pair:p.id,pairName:p.name,members:[...p.members],team:1,plot:j.plot,cents:amount,loss,quality:v.quality,reason:text(v.reason),actor:user().name});log('Pesaje registrado',`${p.name} · ${money(amount/100)} kg · ${v.quality}`);render();toast('Pesaje guardado en la demostración.');}catch(err){$('#kilos-error').textContent=err.message;}}
function editKilos(id){const r=find('records',id);must(role==='jefe'&&r.team===1&&r.date===today&&isOpen(),'Este pesaje no se puede editar.');modal('Corregir pesaje',`<p>${esc(r.pairName)} · ${esc(find('plots',r.plot).name)}</p><div class="form-grid">${field('kilos','Kilos correctos','number',r.cents/100,'required min="0.01" max="999999.99" step="0.01"')}${field('reason','Motivo de la corrección','text','','required maxlength="180"')}</div>`,v=>{must(isOpen(),'La jornada ya está cerrada.');must(text(v.reason),'Indica el motivo de la corrección.');const amount=cents(v.kilos),before=r.cents;r.cents=amount;log('Pesaje corregido',`Registro ${r.id}: ${money(before/100)} → ${money(amount/100)} kg. ${text(v.reason)}`);toast('Corrección guardada y auditada.');});}
function attendanceAction(kind,id){const a=db.attendance.find(a=>a.user===Number(id)&&a.team===1);must(role==='jefe'&&isOpen()&&a,'No es posible modificar esta asistencia.');if(kind==='absent'){must(!a.entry,'No puedes marcar ausente a alguien con entrada.');a.absent=true;log('Inasistencia registrada',find('users',id).name);render();toast('Inasistencia registrada.');return;}
 modal(kind==='entry'?'Registrar entrada':'Registrar salida',`<p>${esc(find('users',id).name)} · ${longDate()}</p>${field('time',kind==='entry'?'Hora de entrada':'Hora de salida','time',kind==='entry'?'08:00':'17:00','required')}`,v=>{must(isOpen()&&!a.absent,'La asistencia no se puede modificar.');if(kind==='exit'){must(a.entry&&v.time>a.entry,'La salida debe ser posterior a la entrada.');a.exit=v.time;}else{must(!a.entry,'Ya existe una entrada.');a.entry=v.time;}a.validated=false;log(kind==='entry'?'Entrada registrada':'Salida registrada',`${find('users',id).name} · ${v.time}`);toast('Marca guardada.');});}
function applyReport(form){const v=Object.fromEntries(new FormData(form));if(v.from>v.to){$('#report-error').textContent='La fecha final debe ser igual o posterior a la inicial.';return;}$('#report-error').textContent='';const rows=scoped().filter(r=>r.date>=v.from&&r.date<=v.to&&(!v.field||fieldFor(r.plot)?.id===Number(v.field))&&(!v.plot||r.plot===Number(v.plot)));$('#report-content').innerHTML=reportContent(rows);}
function exportCsv(){const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Fecha','Hora','Collera','Cuadrilla','Cuartel','Calidad','Kilos','Merma kg'],...reportRows.map(r=>[r.date,r.time,r.pairName,find('teams',r.team)?.name,find('plots',r.plot)?.name,r.quality,(r.cents/100).toFixed(2),(r.loss/100).toFixed(2)])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`agrokodit-produccion-${today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);log('Reporte CSV exportado',`${reportRows.length} pesajes · ${labels[role]}`);toast('Reporte CSV descargado.');}
function bindPage(){document.title=`${navItems.find(n=>n[0]===currentPage)?.[1]} · AgroKODIT`;$('#profile')?.addEventListener('change',e=>navigateRole(e.target.value));$('#kilos-form')?.addEventListener('submit',e=>{e.preventDefault();submitKilos(e.target);});$('#report-filters')?.addEventListener('submit',e=>{e.preventDefault();applyReport(e.target);});const filterUsers=()=>{const q=$('#user-search').value.toLowerCase().trim(),r=$('#user-role').value;let matches=0;document.querySelectorAll('[data-search]').forEach(row=>{row.hidden=!(row.dataset.search.includes(q)&&(!r||row.dataset.role===r));if(!row.hidden)matches++;});$('#user-empty').hidden=matches>0;};$('#user-search')?.addEventListener('input',filterUsers);$('#user-role')?.addEventListener('change',filterUsers);$('#report-filters')&&applyReport($('#report-filters'));$('#f-field')?.addEventListener('change',e=>{const value=Number(e.target.value);$('#f-plot').innerHTML=option('','Todos los cuarteles')+db.plots.filter(p=>!value||fieldFor(p.id)?.id===value).map(p=>option(p.id,p.name)).join('');});}
const adminActions=new Set(['new-user','new-field','edit-field','new-orchard','new-plot','toggle-field','toggle-plot','new-season','close-season','new-pair','new-team','move-pair','deactivate-pair','reopen']);
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=Number(target.dataset.id);try{
 if(adminActions.has(action))must(role==='admin','Esta acción corresponde al administrador.');
 if(action==='enter')return navigateRole(target.dataset.role);
 if(action==='logout'){active=false;return render();}
 if(action==='menu'||action==='menu-close'){$('#sidebar').classList.toggle('open',action==='menu');$('.mobile-overlay').classList.toggle('visible',action==='menu');$('.mobile-menu').setAttribute('aria-expanded',action==='menu');return;}
 if(action==='modal-close')return $('#modal').close();
 if(action==='new-user')return newUser();
 if(action==='new-field'||action==='edit-field')return fieldModal(id);
 if(action==='new-orchard')return newOrchard(id);
 if(action==='new-plot')return newPlot(id);
 if(action==='toggle-field'||action==='toggle-plot'){const item=find(action==='toggle-field'?'fields':'plots',id);return confirmModal(item.active?'Desactivar sector':'Activar sector',`${esc(item.name)} conservará todos sus registros históricos.`,()=>{item.active=!item.active;log(item.active?'Sector activado':'Sector desactivado',item.name);toast('Estado actualizado.');});}
 if(action==='new-season')return newSeason();
 if(action==='close-season'){const s=find('seasons',id);return confirmModal('Cerrar temporada',`Vas a cerrar ${esc(s.name)}. Las jornadas y pesajes de esta demostración quedarán en modo de solo lectura.`,()=>{s.active=false;for(const j of db.journals){j.closed=true;j.closedAt=new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'});j.closedBy=user().name;}log('Temporada cerrada',s.name);toast('Temporada cerrada.');});}
 if(action==='new-pair')return newPair();
 if(action==='new-team')return modal('Nueva cuadrilla',`<div class="form-grid">${field('name','Nombre de la cuadrilla','text','','required maxlength="80"')}${select('chief','Jefe responsable',db.users.filter(u=>u.role==='jefe'&&u.active).map(u=>option(u.id,u.name)).join(''),'required')}</div>`,v=>{must(text(v.name),'Ingresa un nombre.');must(!db.teams.some(t=>t.name.toLowerCase()===text(v.name).toLowerCase()),'La cuadrilla ya existe.');db.teams.push({id:nextId('teams'),name:text(v.name),chief:Number(v.chief)});log('Cuadrilla creada',text(v.name));toast('Cuadrilla creada.');});
 if(action==='move-pair'){const p=find('pairs',id);return modal('Trasladar collera',`<p>${esc(p.name)}: el traslado se aplicará a partir de la próxima jornada. La asistencia y los pesajes de hoy conservarán su cuadrilla.</p>${select('team','Cuadrilla de destino',db.teams.filter(t=>t.id!==p.team).map(t=>option(t.id,t.name)).join(''),'required')}`,v=>{const team=Number(v.team);must(find('teams',team)&&team!==p.team,'Selecciona otra cuadrilla.');p.pendingTeam=team;log('Collera trasladada',`${p.name} → ${find('teams',team).name}. Vigencia: próxima jornada.`);toast('Traslado guardado para la próxima jornada.');});}
 if(action==='deactivate-pair'){const p=find('pairs',id);return confirmModal('Desarmar collera',`Los integrantes de ${esc(p.name)} quedarán disponibles. La producción histórica conservará sus integrantes originales.`,()=>{p.active=false;log('Collera desarmada',p.name);toast('Trabajadores disponibles para una nueva collera.');});}
 if(action.startsWith('attendance-'))return attendanceAction(action.replace('attendance-',''),id);
 if(action==='validate'){must(role==='jefe'&&isOpen(),'No puedes validar una jornada cerrada.');const marks=db.attendance.filter(a=>a.team===1&&(a.entry||a.absent));marks.forEach(a=>a.validated=true);log('Asistencia validada',`${marks.length} marcas · Cuadrilla Norte`);render();return toast('Asistencia validada.');}
 if(action==='edit-kilos')return editKilos(id);
 if(action==='confirm-close'){must(role==='jefe'&&isOpen(),'La jornada no se puede cerrar.');const att=db.attendance.filter(a=>a.team===1);return confirmModal('Confirmar cierre de jornada',`Producción: <strong>${money(total(currentRecords()))} kg</strong>. Presentes: ${att.filter(a=>a.entry).length}. Sin salida: ${att.filter(a=>a.entry&&!a.exit).length}.<br><br>Los registros quedarán bloqueados hasta que un administrador reabra con un motivo.`,v=>{must(v.confirm==='on','Debes confirmar que revisaste el resumen.');const j=journal();j.closed=true;j.closedAt=new Date().toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'});j.closedBy=user().name;log('Jornada cerrada','Cuadrilla Norte · pesajes y asistencia bloqueados');toast('Jornada cerrada.');},'<label class="check-label"><input type="checkbox" name="confirm" required>Revisé la asistencia y los kilos y confirmo el cierre.</label>');}
 if(action==='reopen')return modal('Reabrir jornada',`<p>Esta excepción habilita nuevamente las correcciones y se registra en la bitácora.</p>${field('reason','Motivo de reapertura','text','','required minlength="8" maxlength="180"')}`,v=>{must(seasonOpen(),'No se puede reabrir una jornada sin temporada vigente.');must(text(v.reason).length>=8,'Describe el motivo con al menos 8 caracteres.');const j=journal(id);must(j?.closed,'La jornada ya está abierta.');j.closed=false;log('Jornada reabierta',`${find('teams',id).name}: ${text(v.reason)}`);toast('Jornada reabierta con motivo.');});
 if(action==='export')return exportCsv();
 if(action==='print')return window.print();
 if(action==='reset')return confirmModal('Restablecer demostración','Se reemplazarán los cambios de este prototipo por los datos de ejemplo originales. Tu base de datos de Django no se modifica.',()=>{db=initialData();save();toast('Demostración restablecida.');});
 }catch(err){toast(err.message);}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
